from pathlib import Path
from base64 import b64encode

ROOT = Path(__file__).resolve().parent

def data(name, mime):
    return 'data:' + mime + ';base64,' + b64encode((ROOT/'assets'/name).read_bytes()).decode()

mark='<svg viewBox="0 0 40 40" aria-hidden="true"><path fill="currentColor" d="M5 7h14l.5.6v7.8l-.5.6H2L5 7Zm16 0h14l3 9H21l-.5-.6V7.6L21 7ZM16 17h8l1 1v15l-1 1h-8l-1-1V18l1-1Z"/></svg>'
logo='<div class="logo">'+mark+'<span>thesis</span></div>'
art=data('conviction-workshop.webp','image/webp')
font=data('geist-latin.woff2','font/woff2')
images={k:data('mobile-'+k+'.png','image/png') for k in ['explore','thesis','allocation']}
slides=[]

def slide(body, kind='', label=''):
    n=len(slides)+1
    slides.append('<section class="slide '+kind+'">'+('<header>'+logo+'<span class="label">'+label+'</span></header>')+body+'<footer class="footer"><a href="https://tradethesis.xyz">tradethesis.xyz</a><span>September 2026 · '+str(n).zfill(2)+'</span></footer></section>')

slide(f'''<div class="cover-copy"><p class="eyebrow">Ideas into investments</p><h1>Buy what<br>you <em>believe.</em></h1><p class="lead">Turn a belief about the world into<br>a basket of tokenized stocks.</p><p class="small">Built on Solana. Starting with a clear thesis.</p></div><img class="cover-art" src="{art}" alt="An architectural paper city joined by vermilion ribbons"><div class="cover-tag">Product &amp; partnership brief<br><strong>Kayle · Builder</strong></div>''','cover','Investor & partner introduction')

slide('''<h2>A great investment idea<br>is a terrible to-do list.</h2><p class="lead muted">The belief is clear. Turning it into a position takes work.</p><div class="friction"><div><span class="step">01</span><h3>Find an idea</h3><p>A thread, a report,<br>a strong conviction.</p></div><span class="flow-arrow">→</span><div><span class="step">02</span><h3>Pick exposure</h3><p>Which businesses<br>actually benefit?</p></div><span class="flow-arrow">→</span><div><span class="step">03</span><h3>Assemble trades</h3><p>Choose weights.<br>Buy each asset.</p></div><span class="flow-arrow">→</span><div><span class="step">04</span><h3>Keep the reason</h3><p>What would make<br>you change your mind?</p></div></div><div class="bottom-statement">Our first user: a self-directed investor with USDC,<br>a Solana wallet, and a view on where the world is going.</div><p class="note">Initial audience hypothesis. Trading access is limited to eligible markets.</p>''','dark','01 / The problem')

slide('''<div class="two-col"><div><p class="eyebrow">The product unit is a thesis</p><h2>One idea.<br>Three businesses.<br><em>Your conviction.</em></h2><p class="lead">Understand the claim, inspect the exposure,<br>and choose your own allocation.</p></div><div class="thesis-paper"><div class="paper-kicker">THESIS / FINANCIAL INFRASTRUCTURE</div><h3>Financial activity<br>moves onchain.</h3><p>One claim, expressed through three<br>different business models.</p><div class="allocation-line"><span>COINx</span><div style="width:160px"></div><strong>40%</strong></div><div class="allocation-line"><span>CRCLx</span><div style="width:120px"></div><strong>30%</strong></div><div class="allocation-line"><span>HOODx</span><div style="width:120px"></div><strong>30%</strong></div><div class="paper-foot">Evidence for · Evidence against · Your weights</div></div></div><p class="note">Illustrative allocation from the product. Public browsing and allocation editing work today; integrated checkout is the next release.</p>''','','02 / The solution')

slide('''<h2>Make the investment<br>logic visible.</h2><p class="lead">Example thesis: “Financial activity moves onchain.”</p><div class="holdings"><div><span class="holding-letter pine">C</span><h3>Coinbase</h3><span class="weight">40%</span><p class="role">The exchange</p><p>Trading, custody, and<br>access to onchain activity.</p></div><div><span class="holding-letter clay">C</span><h3>Circle</h3><span class="weight">30%</span><p class="role">The dollar</p><p>Stablecoin infrastructure<br>and reserve economics.</p></div><div><span class="holding-letter slate">R</span><h3>Robinhood</h3><span class="weight">30%</span><p class="role">The brokerage</p><p>Retail access and<br>distribution.</p></div></div><div class="counter"><span>↔</span><div><strong>The case against is part of the product.</strong><p>Onchain activity can grow while fees compress or value accrues somewhere else.</p></div></div><p class="note">Illustrative exposure, not a return forecast or recommendation. <a href="https://tradethesis.xyz/t/financial-activity-moves-onchain">Read the thesis and its sources ↗</a></p>''','','03 / A concrete example')

slide(f'''<div class="demo-title"><h2>From “I agree”<br>to “here’s my take.”</h2><p class="lead">Real screens from the current build.<br>No wallet needed to explore.</p><div class="demo-key"><span>01</span><p>Find a belief<br><small>Browse the catalogue.</small></p><span>02</span><p>Read the argument<br><small>Inspect sources and tradeoffs.</small></p><span>03</span><p>Make it yours<br><small>Adjust each holding’s weight.</small></p></div><p class="small">Public allocation preview.<br>No orders are placed in these screens.</p></div><div class="phones"><div class="phone p-one"><img src="{images['explore']}" alt="Thesis mobile catalogue"></div><div class="phone p-two"><img src="{images['thesis']}" alt="Thesis mobile research page"></div><div class="phone p-three"><img src="{images['allocation']}" alt="Thesis mobile allocation editor"></div></div>''','demo','04 / Product experience')

slide('''<h2>The assets are here.<br>The next layer is the decision.</h2><p class="lead">Solana connects the funding, the trades, and the ownership.</p><div class="rails"><div><span>START</span><h3>Your wallet</h3><p>USDC funding</p></div><b>→</b><div><span>DECIDE</span><h3>Thesis</h3><p>Reasoning + allocation</p></div><b>→</b><div><span>EXECUTE</span><h3>Jupiter</h3><p>Constituent swaps</p></div><b>→</b><div><span>OWN</span><h3>Your wallet</h3><p>Individual stock tokens</p></div></div><div class="rail-notes"><p><strong>Existing assets.</strong><br>xStocks supports tokenized<br>equities on Solana.</p><p><strong>Existing trade infrastructure.</strong><br>Jupiter documents an order,<br>sign, and execute flow.</p><p><strong>A focused app layer.</strong><br>One allocation plan, with each<br>purchase confirmed separately.</p></div><p class="note">Target execution design; public checkout is not yet connected. Access and liquidity must be validated per market and asset.<br>Sources: <a href="https://xstocks.com/partner">xStocks integration information</a> · <a href="https://developers.jup.ag/docs/swap/order-and-execute">Jupiter order &amp; execute documentation</a></p>''','vermilion','05 / Why Solana')

slide('''<h2>The asset is the stock.<br><em>The product is the reasoning.</em></h2><div class="comparison"><div><p class="eyebrow">Distribution</p><h3>A post starts<br>the conversation.</h3><p>Use existing social channels<br>to bring people to an idea.</p></div><div><p class="eyebrow">Exposure</p><h3>A basket expresses<br>the investment.</h3><p>Show the businesses, roles,<br>weights, and limitations.</p></div><div class="comparison-focus"><p class="eyebrow">Thesis’s intended edge</p><h3>Keep the reason<br>with the position.</h3><p>Carry the claim, sources, and<br>review conditions forward.</p></div></div><div class="edge-line"><strong>What can compound</strong><p>Trusted curators → useful evidence updates → repeat decisions</p></div><p class="note">Positioning and retention hypothesis. Versioned research exists today; position-linked updates and creator distribution are planned.</p>''','','06 / Differentiation')

slide('''<div class="two-col gtm"><div><p class="eyebrow">Founder-led distribution</p><h2>Earn the<br>first <em>50.</em></h2><p class="lead">One useful thesis.<br>One trusted introduction<br>at a time.</p><p class="small">Recruit existing wallet users<br>in eligible markets.</p></div><div class="recruit"><div><span class="recruit-num">10</span><div><h3>Hands-on design partners</h3><p>Personally recruit investors who already<br>hold USDC. Watch them use the product.</p></div></div><div><span class="recruit-num">40</span><div><h3>Readers from five curators</h3><p>Target eight additional testers per curator.<br>Share a specific thesis, then host a walkthrough.</p></div></div><div class="retention"><h3>Give them a reason to return.</h3><p>Publish an evidence update and ask:<br>“Does this change your allocation?”</p></div></div></div><p class="note">Acquisition targets, not existing users or committed partnerships. Track completed walkthroughs before funded activation.</p>''','','07 / Go to market')

slide('''<h2>Free to understand.<br>Pay for an ongoing workflow.</h2><p class="lead muted">Monetize useful research and tools once repeat use is proven.</p><div class="business"><div><span class="step">TODAY</span><h3>Open discovery</h3><p>Public theses and allocation previews.<br>No added Thesis fee in the MVP.</p></div><div><span class="step">TEST NEXT</span><h3>Investor subscription</h3><p>Proposed: evidence monitoring,<br>portfolio overlap, and review tools.</p></div><div><span class="step">EXPAND LATER</span><h3>Curator &amp; partner tools</h3><p>Proposed: publishing workflows and<br>embedded thesis distribution.</p></div></div><div class="business-principle">The first business test: will a returning user<br>pay for better ongoing decisions?</div><p class="note">Business-model hypotheses. Pricing and willingness to pay are unvalidated. Third-party trading costs would still apply.</p>''','dark','08 / Business model')

slide('''<h2>A working product surface.<br>A focused path to live use.</h2><div class="build-columns"><div><p class="eyebrow">Available in the current build</p><h3>Research &amp; allocation</h3><ul><li>Three published, sourced theses</li><li>Supporting and opposing evidence</li><li>Adjustable three-stock allocations</li><li>Mobile research and allocation flow</li><li>Published versions in the data model</li></ul><a class="text-link" href="https://t.me/kayle_build">Private repository · access on request ↗</a></div><div><p class="eyebrow">Next release gate</p><h3>Purchase → own → exit</h3><ul><li>Connect the public checkout flow</li><li>Verify a full purchase-to-sale journey</li><li>Prove recovery after a partial fill</li><li>Show holdings tied to the chosen thesis</li><li>Validate market access and eligibility</li></ul></div></div><p class="note">Pre-pilot stage. Public screens are previews; no user, revenue, or funded-volume traction is claimed in this deck.</p>''','','09 / Build status')

slide('''<h2>Prove the loop<br>before expanding the catalogue.</h2><div class="milestones"><div><span class="milestone-dot">1</span><div><p class="eyebrow">Reliability gate</p><h3>A complete round trip</h3><p>Complete an eligible purchase and sale, with reload recovery that never duplicates a fill.</p></div></div><div><span class="milestone-dot">2</span><div><p class="eyebrow">Demand gate</p><h3>A small, funded pilot</h3><p>Target 20 eligible participants over two weeks.<br>Learning threshold: five voluntary purchases; three buyers return within seven days.</p></div></div><div><span class="milestone-dot">3</span><div><p class="eyebrow">Retention &amp; revenue gate</p><h3>An evidence update worth revisiting</h3><p>Bring holders back with new evidence, then test paid tools with repeat users.</p></div></div></div><p class="note">Proposed validation plan, not achieved metrics or a revenue forecast. Pilot purchases depend on live execution and access readiness.</p>''','','10 / Next milestones')

slide(f'''<div class="closing-copy"><p class="eyebrow">Let’s make conviction investable.</p><h2>Good ideas deserve<br><em>a path to ownership.</em></h2><p class="lead">Seeking pilot introductions, research curators,<br>and wallet or distribution partners.</p><div class="founder"><strong>Kayle</strong><span>Builder</span><a href="https://t.me/kayle_build">Telegram · @kayle_build ↗</a></div><div class="closing-links"><a href="https://tradethesis.xyz">Explore Thesis ↗</a><a href="https://t.me/kayle_build">Request repository access ↗</a></div></div><img class="closing-art" src="{art}" alt="Thesis paper city"><p class="note">Product preview · Seeking pilot and distribution conversations.</p>''','closing','11 / Build with us')

